  ('src_iso_15031', 'ISO 15031 — Communication entre véhicule et équipement de diagnostic', 'ISO', 'official', '15031', '2015-01-01', 'https://www.iso.org/standard/66344.html', NULL),
  ('src_iso_15765', 'ISO 15765 — Diagnostic sur CAN (DoCAN)', 'ISO', 'official', '15765', '2016-01-01', 'https://www.iso.org/standard/66574.html', NULL),
  ('src_xamoto_practice', 'Base de pratique d’atelier XAMOTO', 'XAMOTO', 'xamoto', '1.0.0', '2026-01-01', NULL, 'Documentation du projet XAMOTO'),
  ('src_maintenance_ranges', 'Intervalles d’entretien usuels — plages publiées par les constructeurs', 'Synthèse XAMOTO à partir de carnets d’entretien constructeurs', 'technical', '1.0.0', '2026-01-01', NULL, 'XAMOTO publie des PLAGES, jamais des valeurs constructeur officielles. Le carnet d’entretien du véhicule reste la référence.'),
  ('src_african_context', 'Contexte d’usage africain — chaleur, poussière, carburant, trafic urbain', 'XAMOTO (retours terrain Sénégal)', 'xamoto', '1.0.0', '2026-01-01', NULL, 'Documentation du projet XAMOTO'),
  ('src_iso_14229', 'ISO 14229-1 — Services de diagnostic unifiés (UDS)', 'ISO', 'official', '14229-1:2020', '2020-02-01', NULL, 'Norme payante. Sert ici à expliquer une LIMITE : les données hors groupe motopropulseur (freinage, airbag, boîte automatique) passent par des services étendus ou des protocoles constructeur, pas par l’OBD standard.'),
  ('src_workshop_methods', 'Méthodes d’atelier usuelles — freinage, réseau CAN, climatisation, transmission, embrayage, suspension', 'Synthèse XAMOTO à partir de méthodes d’atelier publiées', 'technical', '1.0.0', '2026-01-01', NULL, 'XAMOTO restitue des MÉTHODES, des ORDRES DE VÉRIFICATION et des RÈGLES DE SÉCURITÉ, jamais des valeurs constructeur, des couples de serrage ou des capacités. La documentation du constructeur reste la référence.'),
