  ('P0302', 'Cylinder 2 misfire detected', 'Ratés d’allumage détectés sur le cylindre 2. Le cylindre concerné ne participe pas correctement à la combustion.', 'Cylinder 2 misfire detected. The affected cylinder does not contribute correctly to combustion.', 'allumage', 'important', 'limited', '["Le carburant non brûlé dégrade le catalyseur.","Risque de surchauffe localisée et de détérioration du moteur si le défaut persiste.","Consommation en hausse et perte de puissance."]', '[{"key":"ignition_coil_2","labelFr":"Bobine d’allumage cylindre 2","labelEn":"Ignition coil cylinder 2","baseRate":0.28,"explainsCodes":["P0302","P0300"],"confirmedBy":"test_ignition_spark_check","parts":["bobine_allumage","bougie_allumage"]},{"key":"spark_plug_2","labelFr":"Bougie d’allumage cylindre 2","labelEn":"Spark plug cylinder 2","baseRate":0.24,"explainsCodes":["P0302","P0300"],"confirmedBy":"test_ignition_spark_check","parts":["bougie_allumage"]},{"key":"injector_2","labelFr":"Injecteur cylindre 2","labelEn":"Injector cylinder 2","baseRate":0.16,"explainsCodes":["P0302","P0300","P0171"],"confirmedBy":"test_injector_balance","parts":["injecteur"]},{"key":"compression_low","labelFr":"Compression insuffisante (soupape, segment, joint)","labelEn":"Low compression (valve, ring, gasket)","baseRate":0.12,"explainsCodes":["P0302","P0300"],"confirmedBy":"test_compression"},{"key":"vacuum_leak","labelFr":"Prise d’air à l’admission","labelEn":"Intake vacuum leak","baseRate":0.1,"explainsCodes":["P0171","P0300","P0301"],"confirmedBy":"test_vacuum_leak"},{"key":"fuel_pressure_low","labelFr":"Pression carburant insuffisante (pompe, filtre)","labelEn":"Insufficient fuel pressure (pump, filter)","baseRate":0.1,"explainsCodes":["P0087","P0171"],"confirmedBy":"test_fuel_pressure","parts":["filtre_carburant","pompe_carburant"]}]', '["engine_rpm","engine_load","coolant_temp","short_fuel_trim_b1","long_fuel_trim_b1","o2_b1s1_voltage","maf_air_flow","misfire_count"]', '["test_ignition_spark_check","test_i