  ('P0303', 'Cylinder 3 misfire detected', 'Ratés d’allumage détectés sur le cylindre 3. Le cylindre concerné ne participe pas correctement à la combustion.', 'Cylinder 3 misfire detected. The affected cylinder does not contribute correctly to combustion.', 'allumage', 'important', 'limited', '["Le carburant non brûlé dégrade le catalyseur.","Risque de surchauffe localisée et de détérioration du moteur si le défaut persiste.","Consommation en hausse et perte de puissance."]', '[{"key":"ignition_coil_3","labelFr":"Bobine d’allumage cylindre 3","labelEn":"Ignition coil cylinder 3","baseRate":0.28,"explainsCodes":["P0303","P0300"],"confirmedBy":"test_ignition_spark_check","parts":["bobine_allumage","bougie_allumage"]},{"key":"spark_plug_3","labelFr":"Bougie d’allumage cylindre 3","labelEn":"Spark plug cylinder 3","baseRate":0.24,"explainsCodes":["P0303","P0300"],"confirmedBy":"test_ignition_spark_check","parts":["bougie_allumage"]},{"key":"injector_3","labelFr":"Injecteur cylindre 3","labelEn":"Injector cylinder 3","baseRate":0.16,"explainsCodes":["P0303","P0300","P0171"],"confirmedBy":"test_injector_balance","parts":["injecteur"]},{"key":"compression_low","labelFr":"Compression insuffisante (soupape, segment, joint)","labelEn":"Low compression (valve, ring, gasket)","baseRate":0.12,"explainsCodes":["P0303","P0300"],"confirmedBy":"test_compression"},{"key":"vacuum_leak","labelFr":"Prise d’air à l’admission","labelEn":"Intake vacuum leak","baseRate":0.1,"explainsCodes":["P0171","P0300","P0301"],"confirmedBy":"test_vacuum_leak"},{"key":"fuel_pressure_low","labelFr":"Pression carburant insuffisante (pompe, filtre)","labelEn":"Insufficient fuel pressure (pump, filter)","baseRate":0.1,"explainsCodes":["P0087","P0171"],"confirmedBy":"test_fuel_pressure","parts":["filtre_carburant","pompe_carburant"]}]', '["engine_rpm","engine_load","coolant_temp","short_fuel_trim_b1","long_fuel_trim_b1","o2_b1s1_voltage","maf_air_flow","misfire_count"]', '["test_ignition_spark_check","test_injector_balance","test_compression","test_vacuum_leak"]', '["P0300","P0171","P0420"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0304', 'Cylinder 4 misfire detected', 'Ratés d’allumage détectés sur le cylindre 4. Le cylindre concerné ne participe pas correctement à la combustion.', 'Cylinder 4 misfire detected. The affected cylinder does not contribute correctly to combustion.', 'allumage', 'important', 'limited', '["Le carburant non brûlé dégrade le catalyseur.","Risque de surchauffe localisée et de détérioration du moteur si le défaut persiste.","Consommation en hausse et perte de puissance."]', '[{"key":"ignition_coil_4","labelFr":"Bobine d’allumage cylindre 4","labelEn":"Ignition coil cylinder 4","baseRate":0.28,"explainsCodes":["P0304","P0300"],"confirmedBy":"test_ignition_spark_check","parts":["bobine_allumage","bougie_allumage"]},{"key":"spark_plug_4","labelFr":"Bougie d’allumage cylindre 4","labelEn":"Spark plug cylinder 4","baseRate":0.24,"explainsCodes":["P0304","P0300"],"confirmedBy":"test_ignition_spark_check","parts":["bougie_allumage"]},{"key":"injector_4","labelFr":"Injecteur cylindre 4","labelEn":"Injector cylinder 4","baseRate":0.16,"explainsCodes":["P0304","P0300","P0171"],"confirmedBy":"test_injector_balance","parts":["injecteur"]},{"key":"compression_low","labelFr":"Compression insuffisante (soupape, segment, joint)","labelEn":"Low compression (valve, ring, gasket)","baseRate":0.12,"explainsCodes":["P0304","P0300"],"confirmedBy":"test_compression"},{"key":"vacuum_leak","labelFr":"Prise d’air à l’admission","labelEn":"Intake vacuum leak","baseRate":0.1,"explainsCodes":["P0171","P0300","P0301"],"confirmedBy":"test_vacuum_leak"},{"key":"fuel_pressure_low","labelFr":"Pression carburant insuffisante (pompe, filtre)","labelEn":"Insufficient fuel pressure (pump, filter)","baseRate":0.1,"explainsCodes":["P0087","P0171"],"confirmedBy":"test_fuel_pressure","parts":["filtre_carburant","pompe_carburant"]}]', '["engine_rpm","engine_load","coolant_temp","short_fuel_trim_b1","long_fuel_trim_b1","o2_b1s1_voltage","maf_air_flow","misfire_count"]', '["test_ignition_spark_check","test_injector_balance","test_compression","test_vacuum_leak"]', '["P0300","P0171","P0420"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0171', 'System too lean (Bank 1)', 'Le mélange air/carburant est trop pauvre sur la banque 1 : trop d’air pour la quantité de carburant injectée. Le calculateur corrige au maximum sans réussir à rétablir l’équilibre.', 'The air/fuel mixture is too lean on bank 1: too much air for the injected fuel. The ECU corrects to its limit without restoring the balance.', 'carburant', 'important', 'with_caution', '["Surchauffe possible de la chambre de combustion.","Ratés d’allumage et à-coups.","Dégradation du catalyseur à terme."]', '[{"key":"vacuum_leak","labelFr":"Prise d’air à l’admission (durite, joint, collecteur)","labelEn":"Intake vacuum leak (hose, gasket, manifold)","baseRate":0.34,"confirmedBy":"test_vacuum_leak","parts":["joint_admission","durite_admission"]},{"key":"maf_dirty","labelFr":"Capteur de débit d’air sale ou défaillant","labelEn":"Dirty or faulty mass air flow sensor","baseRate":0.2,"explainsCodes":["P0171","P0101"],"confirmedBy":"test_maf_reading","parts":["capteur_debit_air"]},{"key":"fuel_pressure_low","labelFr":"Pression carburant trop basse (pompe, filtre, régulateur)","labelEn":"Fuel pressure too low (pump, filter, regulator)","baseRate":0.18,"explainsCodes":["P0171","P0087"],"confirmedBy":"test_fuel_pressure","parts":["filtre_carburant","pompe_carburant","regulateur_pression"]},{"key":"o2_sensor_biased","labelFr":"Sonde O2 amont faussée","labelEn":"Biased upstream O2 sensor","baseRate":0.14,"explainsCodes":["P0171","P0134"],"confirmedBy":"test_o2_sensor_activity","parts":["sonde_o2_amont"]},{"key":"injectors_clogged","labelFr":"Injecteurs encrassés","labelEn":"Clogged injectors","baseRate":0.1,"confirmedBy":"test_injector_balance","parts":["injecteur"]},{"key":"exhaust_leak_before_o2","labelFr":"Fuite d’échappement avant la sonde O2","labelEn":"Exhaust leak before the O2 sensor","baseRate":0.08,"confirmedBy":"test_exhaust_leak"}]', '["long_fuel_trim_b1","short_fuel_trim_b1","o2_b1s1_voltage","maf_air_flow","map_pressure","fuel_pressure","engine_rpm"]', '["test_vacuum_leak","test_maf_reading","test_fuel_pressure","test_o2_sensor_activity"]', '["P0174","P0300","P0420","P0134"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0172', 'System too rich (Bank 1)', 'Le mélange est trop riche sur la banque 1 : trop de carburant pour l’air admis. Le calculateur réduit l’injection au maximum sans retrouver l’équilibre.', 'The mixture is too rich on bank 1: too much fuel for the intake air. The ECU reduces injection to its limit without restoring balance.', 'carburant', 'attention', 'with_caution', '["Encrassement des bougies et du catalyseur.","Consommation excessive.","Ratés d’allumage possibles."]', '[{"key":"injector_leaking","labelFr":"Injecteur qui fuit","labelEn":"Leaking injector","baseRate":0.26,"confirmedBy":"test_injector_balance","parts":["injecteur"]},{"key":"fuel_pressure_high","labelFr":"Pression carburant trop élevée","labelEn":"Fuel pressure too high","baseRate":0.22,"explainsCodes":["P0172","P0088"],"confirmedBy":"test_fuel_pressure","parts":["regulateur_pression"]},{"key":"maf_dirty","labelFr":"Capteur de débit d’air surestimant le débit","labelEn":"MAF sensor over-reporting air flow","baseRate":0.2,"confirmedBy":"test_maf_reading","parts":["capteur_debit_air"]},{"key":"o2_sensor_biased","labelFr":"Sonde O2 amont faussée (bloquée haute)","labelEn":"Biased upstream O2 sensor (stuck high)","baseRate":0.16,"confirmedBy":"test_o2_sensor_activity","parts":["sonde_o2_amont"]},{"key":"air_filter_clogged","labelFr":"Filtre à air très encrassé","labelEn":"Heavily clogged air filter","baseRate":0.14,"parts":["filtre_air"]},{"key":"thermostat_stuck_open","labelFr":"Thermostat bloqué ouvert (moteur froid permanent)","labelEn":"Thermostat stuck open (engine never warm)","baseRate":0.1,"explainsCodes":["P0172","P0128"],"parts":["thermostat"]}]', '["long_fuel_trim_b1","short_fuel_trim_b1","o2_b1s1_voltage","maf_air_flow","coolant_temp","fuel_pressure"]', '["test_injector_balance","test_fuel_pressure","test_maf_reading","test_o2_sensor_activity"]', '["P0175","P0128","P0420"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0087', 'Fuel rail / system pressure — too low', 'La pression de carburant dans la rampe est inférieure à la valeur attendue. Le moteur peut manquer de carburant, surtout en accélération.', 'Fuel rail pressure is below the expected value. The engine may be starved of fuel, especially under acceleration.', 'carburant', 'important', 'limited', '["Coupures d’injection et perte de puissance.","Ratés d’allumage.","Risque d’arrêt moteur en circulation."]', '[{"key":"fuel_filter_clogged","labelFr":"Filtre à carburant colmaté","labelEn":"Clogged fuel filter","baseRate":0.32,"confirmedBy":"test_fuel_pressure","parts":["filtre_carburant"]},{"key":"fuel_pump_weak","labelFr":"Pompe à carburant faible","labelEn":"Weak fuel pump","baseRate":0.28,"confirmedBy":"test_fuel_pressure","parts":["pompe_carburant"]},{"key":"pressure_regulator_faulty","labelFr":"Régulateur de pression défaillant","labelEn":"Faulty pressure regulator","baseRate":0.16,"parts":["regulateur_pression"]},{"key":"leak_in_fuel_line","labelFr":"Fuite sur le circuit d’alimentation","labelEn":"Leak in the fuel supply line","baseRate":0.12,"parts":["durite_carburant"]},{"key":"fuel_quality","labelFr":"Carburant de qualité inadaptée ou présence d’eau","labelEn":"Poor fuel quality or water in fuel","baseRate":0.12}]', '["fuel_pressure","long_fuel_trim_b1","engine_rpm","engine_load"]', '["test_fuel_pressure","test_fuel_quality"]', '["P0171","P0300","P0088"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0088', 'Fuel rail / system pressure — too high', 'La pression de carburant est supérieure à la valeur attendue. Le moteur reçoit trop de carburant.', 'Fuel pressure is above the expected value. The engine receives too much fuel.', 'carburant', 'attention', 'with_caution', '["Mélange trop riche.","Encrassement des bougies.","Surcharge du catalyseur."]', '[{"key":"pressure_regulator_faulty","labelFr":"Régulateur de pression bloqué fermé","labelEn":"Pressure regulator stuck closed","baseRate":0.45,"confirmedBy":"test_fuel_pressure","parts":["regulateur_pression"]},{"key":"return_line_blocked","labelFr":"Conduite de retour bouchée","labelEn":"Blocked return line","baseRate":0.3},{"key":"fuel_pressure_sensor_faulty","labelFr":"Capteur de pression carburant défaillant","labelEn":"Faulty fuel pressure sensor","baseRate":0.25,"parts":["capteur_pression_carburant"]}]', '["fuel_pressure","long_fuel_trim_b1"]', '["test_fuel_pressure"]', '["P0172"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0101', 'Mass air flow (MAF) circuit — range/performance problem', 'La valeur mesurée par le capteur de débit d’air n’est pas cohérente avec ce que le calculateur attend du moteur (régime et charge).', 'The air flow sensor reading is inconsistent with what the ECU expects from the engine (rpm and load).', 'admission', 'attention', 'with_caution', '["Mélange mal dosé.","Consommation anormale.","À-coups et perte de réactivité."]', '[{"key":"maf_dirty","labelFr":"Capteur de débit d’air encrassé","labelEn":"Dirty mass air flow sensor","baseRate":0.42,"confirmedBy":"test_maf_reading","parts":["capteur_debit_air"]},{"key":"air_leak_after_maf","labelFr":"Prise d’air entre le capteur et le moteur","labelEn":"Air leak between sensor and engine","baseRate":0.28,"confirmedBy":"test_vacuum_leak","parts":["durite_admission"]},{"key":"air_filter_clogged","labelFr":"Filtre à air colmaté","labelEn":"Clogged air filter","baseRate":0.18,"parts":["filtre_air"]},{"key":"maf_wiring","labelFr":"Câblage ou connecteur de capteur défectueux","labelEn":"Faulty sensor wiring or connector","baseRate":0.12,"confirmedBy":"test_wiring_visual"}]', '["maf_air_flow","engine_load","engine_rpm","long_fuel_trim_b1","throttle_position"]', '["test_maf_reading","test_vacuum_leak","test_wiring_visual"]', '["P0171","P0102"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0102', 'Mass air flow (MAF) circuit — low input', 'Le signal du capteur de débit d’air est anormalement bas (ou absent).', 'The air flow sensor signal is abnormally low (or absent).', 'admission', 'attention', 'with_caution', '["Mélange mal dosé.","Mode dégradé possible."]', '[{"key":"maf_wiring","labelFr":"Circuit ouvert ou connecteur débranché","labelEn":"Open circuit or disconnected connector","baseRate":0.4,"confirmedBy":"test_wiring_visual"},{"key":"maf_faulty","labelFr":"Capteur de débit d’air défaillant","labelEn":"Faulty mass air flow sensor","baseRate":0.36,"parts":["capteur_debit_air"]},{"key":"air_leak_after_maf","labelFr":"Prise d’air importante après le capteur","labelEn":"Major air leak after the sensor","baseRate":0.14,"confirmedBy":"test_vacuum_leak"},{"key":"ecm_connector","labelFr":"Connecteur calculateur oxydé","labelEn":"Corroded ECU connector","baseRate":0.1}]', '["maf_air_flow","engine_load","engine_rpm"]', '["test_wiring_visual","test_maf_reading","test_vacuum_leak"]', '[]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0106', 'Manifold absolute pressure (MAP) — range/performance problem', 'La pression mesurée dans le collecteur d’admission est incohérente avec le régime et la charge du moteur.', 'Intake manifold pressure does not match engine speed and load.', 'admission', 'attention', 'with_caution', '["Calcul de charge moteur erroné.","Consommation et puissance affectées."]', '[{"key":"map_sensor_faulty","labelFr":"Capteur MAP défaillant","labelEn":"Faulty MAP sensor","baseRate":0.38,"parts":["capteur_map"]},{"key":"map_hose_blocked","labelFr":"Durite de capteur MAP bouchée ou percée","labelEn":"Blocked or split MAP sensor hose","baseRate":0.3},{"key":"map_wiring","labelFr":"Câblage du capteur MAP","labelEn":"MAP sensor wiring","baseRate":0.2,"confirmedBy":"test_wiring_visual"},{"key":"vacuum_leak","labelFr":"Prise d’air à l’admission","labelEn":"Intake vacuum leak","baseRate":0.12,"confirmedBy":"test_vacuum_leak"}]', '["map_pressure","engine_load","engine_rpm","barometric_pressure"]', '["test_map_reading","test_vacuum_leak","test_wiring_visual"]', '[]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0234', 'Turbocharger overboost condition', 'Le turbocompresseur produit une pression supérieure à la consigne. Le calculateur protège le moteur en réduisant la puissance.', 'The turbocharger produces more boost than commanded. The ECU protects the engine by reducing power.', 'admission', 'important', 'limited', '["Coupure de puissance.","Risque mécanique sur le moteur si répété."]', '[{"key":"wastegate_stuck","labelFr":"Wastegate bloquée fermée","labelEn":"Wastegate stuck closed","baseRate":0.4,"parts":["wastegate"]},{"key":"boost_control_valve","labelFr":"Électrovanne de suralimentation défaillante","labelEn":"Faulty boost control solenoid","baseRate":0.3,"parts":["electrovanne_suralimentation"]},{"key":"map_sensor_faulty","labelFr":"Capteur MAP défaillant (mesure fausse)","labelEn":"Faulty MAP sensor (false reading)","baseRate":0.2,"parts":["capteur_map"]},{"key":"boost_hose_leak","labelFr":"Durite de suralimentation percée","labelEn":"Split boost hose","baseRate":0.1}]', '["map_pressure","engine_load","engine_rpm"]', '["test_boost_control","test_map_reading"]', '["P0299"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0299', 'Turbocharger underboost condition', 'Le turbocompresseur ne fournit pas la pression attendue. Le moteur manque de puissance, surtout dans les montées.', 'The turbocharger does not deliver expected boost. The engine lacks power, especially on inclines.', 'admission', 'attention', 'with_caution', '["Perte de puissance marquée.","Mode dégradé fréquent.","Fumée noire possible."]', '[{"key":"boost_hose_leak","labelFr":"Fuite sur le circuit de suralimentation (durite, échangeur)","labelEn":"Leak in the boost circuit (hose, intercooler)","baseRate":0.34,"parts":["durite_suralimentation","echangeur_air"]},{"key":"wastegate_stuck","labelFr":"Wastegate ou géométrie variable bloquée","labelEn":"Wastegate or VNT mechanism stuck","baseRate":0.26,"parts":["wastegate"]},{"key":"turbo_worn","labelFr":"Usure du turbocompresseur","labelEn":"Worn turbocharger","baseRate":0.14,"parts":["turbo"]},{"key":"boost_control_valve","labelFr":"Électrovanne de suralimentation","labelEn":"Boost control solenoid","baseRate":0.14,"parts":["electrovanne_suralimentation"]},{"key":"air_filter_clogged","labelFr":"Filtre à air très colmaté","labelEn":"Heavily clogged air filter","baseRate":0.12,"parts":["filtre_air"]}]', '["map_pressure","maf_air_flow","engine_load"]', '["test_boost_leak","test_boost_control","test_maf_reading"]', '["P0234","P2463"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0217', 'Engine over temperature condition', 'Le moteur a dépassé sa température normale de fonctionnement. C’est un défaut à traiter immédiatement.', 'The engine exceeded its normal operating temperature. This fault must be addressed immediately.', 'moteur', 'critical', 'no', '["Déformation de culasse et destruction du joint de culasse.","Serrage moteur possible.","Risque d’incendie par projection de liquide chaud."]', '[{"key":"coolant_level_low","labelFr":"Niveau de liquide de refroidissement insuffisant (fuite)","labelEn":"Low coolant level (leak)","baseRate":0.34,"parts":["liquide_refroidissement","durite_refroidissement"]},{"key":"fan_not_working","labelFr":"Ventilateur de refroidissement non fonctionnel","labelEn":"Cooling fan not working","baseRate":0.22,"confirmedBy":"test_fan_operation","parts":["moto_ventilateur"]},{"key":"thermostat_stuck_closed","labelFr":"Thermostat bloqué fermé","labelEn":"Thermostat stuck closed","baseRate":0.18,"parts":["thermostat"]},{"key":"water_pump_weak","labelFr":"Pompe à eau faible ou défaillante","labelEn":"Weak or failed water pump","baseRate":0.14,"parts":["pompe_a_eau"]},{"key":"radiator_clogged","labelFr":"Radiateur entartré ou obstrué","labelEn":"Clogged or blocked radiator","baseRate":0.12,"parts":["radiateur"],"confirmedBy":"test_radiator_flow"},{"key":"head_gasket","labelFr":"Joint de culasse défaillant","labelEn":"Failed head gasket","baseRate":0.08,"confirmedBy":"test_combustion_gases_coolant"}]', '["coolant_temp","intake_air_temp","engine_rpm","engine_load"]', '["test_coolant_level","test_fan_operation","test_radiator_flow","test_combustion_gases_coolant"]', '["P0128","P0117","P0118"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0128', 'Coolant thermostat — coolant temperature below regulating temperature', 'Le moteur n’atteint pas sa température normale dans le délai attendu. Le plus souvent, le thermostat reste ouvert.', 'The engine does not reach normal temperature within the expected time. Most often the thermostat stays open.', 'moteur', 'attention', 'with_caution', '["Surconsommation de carburant.","Usure accélérée du moteur (graissage imparfait).","Chauffage inefficace."]', '[{"key":"thermostat_stuck_open","labelFr":"Thermostat bloqué ouvert","labelEn":"Thermostat stuck open","baseRate":0.55,"parts":["thermostat"]},{"key":"coolant_temp_sensor_faulty","labelFr":"Sonde de température moteur faussée","labelEn":"Faulty coolant temperature sensor","baseRate":0.22,"parts":["sonde_temperature_moteur"]},{"key":"coolant_level_low","labelFr":"Niveau de liquide insuffisant","labelEn":"Low coolant level","baseRate":0.13},{"key":"fan_always_on","labelFr":"Ventilateur actif en permanence","labelEn":"Fan running permanently","baseRate":0.1,"confirmedBy":"test_fan_operation"}]', '["coolant_temp","intake_air_temp","runtime_since_start","ambient_temp"]', '["test_warm_up_curve","test_coolant_level","test_fan_operation"]', '["P0217","P0116"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0117', 'Engine coolant temperature sensor 1 circuit — low input', 'Le signal de la sonde de température moteur est incohérent (très bas ou en court-circuit). Le calculateur peut enrichir à tort le mélange.', 'The engine coolant temperature sensor signal is inconsistent (very low or shorted). The ECU may wrongly enrich the mixture.', 'moteur', 'attention', 'with_caution', '["Démarrage difficile à chaud.","Surconsommation.","Fonctionnement du ventilateur erroné."]', '[{"key":"coolant_temp_sensor_faulty","labelFr":"Sonde de température défaillante","labelEn":"Faulty temperature sensor","baseRate":0.45,"parts":["sonde_temperature_moteur"]},{"key":"sensor_wiring_short","labelFr":"Câblage en court-circuit","labelEn":"Short circuit in wiring","baseRate":0.3,"confirmedBy":"test_wiring_visual"},{"key":"coolant_temp_connector","labelFr":"Connecteur oxydé ou débranché","labelEn":"Corroded or disconnected connector","baseRate":0.25,"confirmedBy":"test_wiring_visual"}]', '["coolant_temp","ambient_temp","intake_air_temp"]', '["test_coolant_sensor_compare","test_wiring_visual"]', '["P0118","P0128"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0118', 'Engine coolant temperature sensor 1 circuit — high input', 'Le signal de la sonde de température moteur est anormalement haut (circuit ouvert ou sonde débranchée).', 'The engine coolant temperature signal is abnormally high (open circuit or unplugged sensor).', 'moteur', 'attention', 'with_caution', '["Enrichissement excessif.","Ventilateur déclenché à tort.","Surconsommation."]', '[{"key":"coolant_temp_sensor_faulty","labelFr":"Sonde de température défaillante","labelEn":"Faulty temperature sensor","baseRate":0.4,"parts":["sonde_temperature_moteur"]},{"key":"sensor_wiring_open","labelFr":"Circuit ouvert dans le faisceau","labelEn":"Open circuit in the harness","baseRate":0.35,"confirmedBy":"test_wiring_visual"},{"key":"coolant_temp_connector","labelFr":"Connecteur débranché","labelEn":"Disconnected connector","baseRate":0.25,"confirmedBy":"test_wiring_visual"}]', '["coolant_temp","ambient_temp"]', '["test_coolant_sensor_compare","test_wiring_visual"]', '["P0117"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0420', 'Catalyst system efficiency below threshold (Bank 1)', 'Le véhicule signale une efficacité insuffisante du système catalytique. Plusieurs causes peuvent produire ce défaut : le catalyseur lui-même, mais aussi une sonde O2, une fuite d’échappement ou un autre défaut moteur non encore corrigé.', 'The vehicle reports insufficient catalytic system efficiency. Several causes may produce this fault: the catalyst itself, but also an O2 sensor, an exhaust leak or another uncorrected engine fault.', 'depollution', 'attention', 'with_caution', '["Défaut de contrôle technique (pollution) probable.","Surconsommation légère.","Aucun danger immédiat dans la plupart des cas, mais le défaut masque parfois un autre problème moteur."]', '[{"key":"catalyst_worn","labelFr":"Catalyseur usé ou endommagé","labelEn":"Worn or damaged catalytic converter","baseRate":0.38,"parts":["catalyseur"],"confirmedBy":"test_o2_downstream_activity"},{"key":"o2_downstream_faulty","labelFr":"Sonde O2 aval défaillante","labelEn":"Faulty downstream O2 sensor","baseRate":0.24,"parts":["sonde_o2_aval"],"confirmedBy":"test_o2_sensor_activity"},{"key":"exhaust_leak","labelFr":"Fuite d’échappement en amont de la sonde aval","labelEn":"Exhaust leak upstream of the downstream sensor","baseRate":0.14,"confirmedBy":"test_exhaust_leak"},{"key":"upstream_issue_hidden","labelFr":"Défaut moteur masqué (mélange, ratés, consommation d’huile)","labelEn":"Hidden engine fault (mixture, misfire, oil consumption)","baseRate":0.14,"explainsCodes":["P0171","P0300","P0420"],"confirmedBy":"test_engine_baseline_scan"},{"key":"oil_or_coolant_burning","labelFr":"Consommation d’huile ou de liquide dans l’échappement","labelEn":"Oil or coolant burning in the exhaust","baseRate":0.1}]', '["o2_b1s1_voltage","o2_b1s2_voltage","long_fuel_trim_b1","short_fuel_trim_b1","coolant_temp","misfire_count"]', '["test_o2_sensor_activity","test_o2_downstream_activity","test_exhaust_leak","test_engine_baseline_scan"]', '["P0430","P0171","P0300","P0134"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0134', 'O2 sensor circuit — no activity detected (Bank 1, Sensor 1)', 'La sonde O2 amont ne produit plus de variation de signal. Le calculateur ne peut plus réguler le mélange correctement.', 'The upstream O2 sensor no longer produces a varying signal. The ECU can no longer regulate the mixture correctly.', 'depollution', 'important', 'with_caution', '["Mélange non régulé.","Surconsommation.","Dégradation du catalyseur."]', '[{"key":"o2_upstream_faulty","labelFr":"Sonde O2 amont en fin de vie","labelEn":"Upstream O2 sensor at end of life","baseRate":0.44,"parts":["sonde_o2_amont"],"confirmedBy":"test_o2_sensor_activity"},{"key":"o2_wiring","labelFr":"Câblage ou connecteur de sonde O2","labelEn":"O2 sensor wiring or connector","baseRate":0.24,"confirmedBy":"test_wiring_visual"},{"key":"exhaust_leak_before_o2","labelFr":"Fuite d’échappement avant la sonde","labelEn":"Exhaust leak before the sensor","baseRate":0.18,"confirmedBy":"test_exhaust_leak"},{"key":"sensor_contamination","labelFr":"Sonde contaminée (silicone, additifs, liquide de refroidissement)","labelEn":"Contaminated sensor (silicone, additives, coolant)","baseRate":0.14,"parts":["sonde_o2_amont"]}]', '["o2_b1s1_voltage","long_fuel_trim_b1","short_fuel_trim_b1"]', '["test_o2_sensor_activity","test_exhaust_leak","test_wiring_visual"]', '["P0420","P0171"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0401', 'Exhaust gas recirculation (EGR) flow — insufficient detected', 'Le calculateur constate que la vanne de recirculation des gaz d’échappement ne laisse pas passer le débit attendu : elle est probablement encrassée ou bloquée.', 'The ECU detects that the exhaust gas recirculation valve does not flow the expected amount: it is probably clogged or stuck.', 'depollution', 'attention', 'with_caution', '["Cliquetis (cliquetis moteur) et surchauffe locale.","À-coups à bas régime.","Voyant moteur permanent."]', '[{"key":"egr_clogged","labelFr":"Vanne EGR et conduits encrassés (suie)","labelEn":"Clogged EGR valve and passages (soot)","baseRate":0.46,"parts":["vanne_egr"],"confirmedBy":"test_egr_operation"},{"key":"egr_valve_faulty","labelFr":"Vanne EGR défaillante (moteur de commande)","labelEn":"Faulty EGR valve actuator","baseRate":0.22,"parts":["vanne_egr"]},{"key":"egr_wiring","labelFr":"Câblage ou connecteur de la vanne EGR","labelEn":"EGR valve wiring or connector","baseRate":0.12},{"key":"dpf_partially_clogged","labelFr":"Filtre à particules partiellement colmaté","labelEn":"Partially clogged particulate filter","baseRate":0.1,"explainsCodes":["P0401","P2463","P2002"]},{"key":"map_sensor_faulty","labelFr":"Capteur MAP/MAF faussant le calcul de débit","labelEn":"MAP/MAF sensor corrupting the flow calculation","baseRate":0.1,"confirmedBy":"test_map_reading"}]', '["egr_command","map_pressure","maf_air_flow","engine_load"]', '["test_egr_operation","test_maf_reading","test_dpf_soot_load"]', '["P0402","P2463","P2002"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P2002', 'Particulate filter efficiency below threshold (Bank 1)', 'Le filtre à particules laisse passer davantage de suie que ce qui est attendu. Le filtre est probablement usé ou fissuré.', 'The particulate filter passes more soot than expected. The filter is probably worn or cracked.', 'depollution', 'attention', 'with_caution', '["Refus au contrôle technique.","Régénérations plus fréquentes."]', '[{"key":"dpf_cracked","labelFr":"Filtre à particules fissuré ou percé","labelEn":"Cracked or punctured DPF","baseRate":0.4,"parts":["filtre_particules"]},{"key":"dpf_sensor_faulty","labelFr":"Capteur de pression différentielle défaillant","labelEn":"Faulty differential pressure sensor","baseRate":0.3,"parts":["capteur_pression_differentielle"],"confirmedBy":"test_dpf_pressure_sensor"},{"key":"dpf_hoses","labelFr":"Durites de capteur bouchées ou percées","labelEn":"Blocked or split sensor hoses","baseRate":0.18},{"key":"egr_excess_soot","labelFr":"Excès de suie dû à l’EGR ou à l’injection","labelEn":"Excess soot from EGR or injection","baseRate":0.12,"explainsCodes":["P2002","P0401","P2463"]}]', '["dpf_pressure_delta","egr_command","engine_load"]', '["test_dpf_soot_load","test_dpf_pressure_sensor","test_egr_operation"]', '["P2463","P0401"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P2463', 'Particulate filter — soot accumulation (Bank 1)', 'Le filtre à particules est très chargé en suie. Le véhicule n’a probablement pas pu réaliser ses cycles de régénération (trajets courts, embouteillages, ville).', 'The particulate filter is heavily loaded with soot. The vehicle has probably not been able to complete its regeneration cycles (short trips, traffic, city).', 'depollution', 'important', 'limited', '["Mode dégradé et perte de puissance.","Risque de colmatage définitif du filtre.","Une régénération forcée en atelier peut être nécessaire."]', '[{"key":"dpf_soot_short_trips","labelFr":"Usage urbain / trajets courts empêchant la régénération","labelEn":"Urban use / short trips preventing regeneration","baseRate":0.42,"confirmedBy":"test_driving_profile_review"},{"key":"egr_clogged","labelFr":"EGR encrassée augmentant la production de suie","labelEn":"Clogged EGR increasing soot production","baseRate":0.22,"explainsCodes":["P2463","P0401"],"confirmedBy":"test_egr_operation"},{"key":"injectors_worn","labelFr":"Injecteurs encrassés (injection excessive)","labelEn":"Clogged injectors (excess fuelling)","baseRate":0.16,"confirmedBy":"test_injector_balance"},{"key":"air_filter_clogged","labelFr":"Filtre à air colmaté","labelEn":"Clogged air filter","baseRate":0.1,"parts":["filtre_air"]},{"key":"dpf_additive_low","labelFr":"Additif FAP/AdBlue insuffisant (selon système)","labelEn":"Low DPF/AdBlue additive (depending on system)","baseRate":0.1}]', '["dpf_pressure_delta","egr_command","engine_load","coolant_temp"]', '["test_dpf_soot_load","test_driving_profile_review","test_egr_operation"]', '["P2002","P0401"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0442', 'Evaporative emission system — small leak detected', 'Une petite fuite est détectée dans le circuit de récupération des vapeurs de carburant. Cela n’affecte généralement pas la conduite.', 'A small leak is detected in the fuel vapour recovery system. This generally does not affect driving.', 'depollution', 'normal', 'yes', '["Voyant moteur allumé.","Problème de contrôle technique pollution.","Odeur de carburant possible."]', '[{"key":"fuel_cap_seal","labelFr":"Bouchon de réservoir mal fermé ou joint usé","labelEn":"Loose or worn fuel cap seal","baseRate":0.52,"parts":["bouchon_reservoir"],"confirmedBy":"test_fuel_cap"},{"key":"evap_hose_cracked","labelFr":"Durite de canister fendue","labelEn":"Cracked canister hose","baseRate":0.2,"parts":["durite_canister"]},{"key":"purge_valve_faulty","labelFr":"Électrovanne de purge défaillante","labelEn":"Faulty purge solenoid","baseRate":0.16,"parts":["electrovanne_purge"]},{"key":"charcoal_canister","labelFr":"Canister endommagé","labelEn":"Damaged charcoal canister","baseRate":0.12,"parts":["canister"]}]', '["long_fuel_trim_b1","fuel_level"]', '["test_fuel_cap","test_wiring_visual"]', '["P0455","P0456"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0455', 'Evaporative emission system — large leak detected', 'Une fuite importante est détectée dans le circuit de récupération des vapeurs de carburant (ou bouchon ouvert).', 'A large leak is detected in the fuel vapour recovery system (or the cap is open).', 'depollution', 'attention', 'with_caution', '["Émissions non conformes.","Odeur de carburant.","Voyant moteur permanent."]', '[{"key":"fuel_cap_missing","labelFr":"Bouchon absent, mal fermé ou joint détérioré","labelEn":"Cap missing, loose or damaged seal","baseRate":0.58,"parts":["bouchon_reservoir"],"confirmedBy":"test_fuel_cap"},{"key":"evap_hose_disconnected","labelFr":"Durite débranchée ou percée","labelEn":"Disconnected or punctured hose","baseRate":0.24},{"key":"fuel_tank_seal","labelFr":"Joint de jauge ou de réservoir","labelEn":"Fuel gauge or tank seal","baseRate":0.18}]', '["fuel_level"]', '["test_fuel_cap","test_wiring_visual"]', '["P0442"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0562', 'System voltage — low', 'La tension du réseau électrique du véhicule est trop basse. L’origine peut être la batterie, l’alternateur, la courroie d’accessoires ou les connexions.', 'Vehicle system voltage is too low. The cause may be the battery, the alternator, the accessory belt or the connections.', 'electrique', 'important', 'with_caution', '["Démarrages difficiles puis impossibles.","Défaillances électroniques en cascade (capteurs, calculateurs).","Risque d’arrêt moteur en circulation sur les véhicules récents."]', '[{"key":"battery_worn","labelFr":"Batterie en fin de vie","labelEn":"Battery at end of life","baseRate":0.36,"parts":["batterie"],"confirmedBy":"test_battery_rest_voltage"},{"key":"alternator_weak","labelFr":"Alternateur faible ou défaillant","labelEn":"Weak or failed alternator","baseRate":0.26,"parts":["alternateur"],"confirmedBy":"test_charging_voltage"},{"key":"belt_tension","labelFr":"Courroie d’accessoires détendue ou usée","labelEn":"Loose or worn accessory belt","baseRate":0.14,"parts":["courroie_accessoires"]},{"key":"battery_terminals","labelFr":"Bornes et cosses oxydées ou desserrées","labelEn":"Corroded or loose battery terminals","baseRate":0.12},{"key":"parasitic_drain","labelFr":"Consommateur parasite (décharge à l’arrêt)","labelEn":"Parasitic drain (discharge when parked)","baseRate":0.08,"confirmedBy":"test_parasitic_drain"},{"key":"ground_strap","labelFr":"Masse moteur ou châssis défectueuse","labelEn":"Faulty engine or chassis ground","baseRate":0.04}]', '["battery_voltage","engine_rpm","coolant_temp"]', '["test_battery_rest_voltage","test_charging_voltage","test_parasitic_drain","test_wiring_visual"]', '["P0563","P0335"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0563', 'System voltage — high', 'La tension du réseau est trop élevée, ce qui suggère un problème de régulation de l’alternateur.', 'System voltage is too high, suggesting an alternator regulation problem.', 'electrique', 'important', 'limited', '["Surcharge de la batterie.","Détérioration des ampoules et des calculateurs."]', '[{"key":"alternator_regulator","labelFr":"Régulateur d’alternateur défaillant","labelEn":"Faulty alternator regulator","baseRate":0.5,"parts":["alternateur"],"confirmedBy":"test_charging_voltage"},{"key":"alternator_wiring","labelFr":"Câblage de régulation","labelEn":"Regulation wiring","baseRate":0.3},{"key":"battery_faulty","labelFr":"Batterie défaillante (ne lisse plus la tension)","labelEn":"Failed battery (no longer smoothing voltage)","baseRate":0.2,"parts":["batterie"]}]', '["battery_voltage","engine_rpm"]', '["test_charging_voltage","test_battery_rest_voltage"]', '["P0562"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0335', 'Crankshaft position sensor A circuit malfunction', 'Le calculateur ne reçoit plus correctement l’information de position du vilebrequin. Sans cette information, il ne peut pas gérer l’allumage ni l’injection : le moteur peut caler ou ne pas démarrer.', 'The ECU no longer receives a correct crankshaft position signal. Without it, ignition and injection cannot be managed: the engine may stall or fail to start.', 'allumage', 'critical', 'no', '["Moteur qui cale sans prévenir, éventuellement en circulation.","Démarrage impossible.","Un calage en circulation présente un risque immédiat."]', '[{"key":"crank_sensor_faulty","labelFr":"Capteur de position vilebrequin défaillant","labelEn":"Faulty crankshaft position sensor","baseRate":0.46,"parts":["capteur_vilebrequin"],"confirmedBy":"test_crank_sensor_signal"},{"key":"crank_sensor_wiring","labelFr":"Câblage ou connecteur du capteur","labelEn":"Sensor wiring or connector","baseRate":0.24,"confirmedBy":"test_wiring_visual"},{"key":"crank_target_ring","labelFr":"Couronne dentée abîmée ou encrassée","labelEn":"Damaged or dirty reluctor ring","baseRate":0.14},{"key":"voltage_instability","labelFr":"Tension d’alimentation instable (batterie/alternateur)","labelEn":"Unstable supply voltage (battery/alternator)","baseRate":0.1,"explainsCodes":["P0335","P0562"],"confirmedBy":"test_battery_rest_voltage"},{"key":"ecm_issue","labelFr":"Défaut interne du calculateur","labelEn":"Internal ECU fault","baseRate":0.06}]', '["engine_rpm","battery_voltage","coolant_temp"]', '["test_crank_sensor_signal","test_battery_rest_voltage","test_wiring_visual"]', '["P0340","P0562"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0340', 'Camshaft position sensor A circuit malfunction (Bank 1)', 'Le calculateur ne reçoit plus correctement l’information de position de l’arbre à cames, ce qui perturbe la synchronisation de l’injection et de l’allumage.', 'The ECU no longer receives a correct camshaft position signal, disturbing injection and ignition synchronisation.', 'allumage', 'important', 'limited', '["Démarrages difficiles.","Perte de puissance.","Mode dégradé."]', '[{"key":"cam_sensor_faulty","labelFr":"Capteur d’arbre à cames défaillant","labelEn":"Faulty camshaft position sensor","baseRate":0.42,"parts":["capteur_arbre_a_cames"],"confirmedBy":"test_cam_sensor_signal"},{"key":"cam_sensor_wiring","labelFr":"Câblage ou connecteur","labelEn":"Wiring or connector","baseRate":0.24,"confirmedBy":"test_wiring_visual"},{"key":"timing_stretched","labelFr":"Chaîne ou courroie de distribution détendue / décalée","labelEn":"Stretched or jumped timing chain or belt","baseRate":0.2,"explainsCodes":["P0340","P0016"],"confirmedBy":"test_timing_alignment"},{"key":"oil_sludge","labelFr":"Dépôts d’huile sur le déphaseur (moteurs à calage variable)","labelEn":"Oil deposits on the phaser (variable timing engines)","baseRate":0.14,"parts":["huile_moteur","filtre_huile"]}]', '["engine_rpm","coolant_temp","oil_temp"]', '["test_cam_sensor_signal","test_timing_alignment","test_wiring_visual"]', '["P0016","P0335"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0016', 'Crankshaft/camshaft position correlation (Bank 1, Sensor A)', 'La position de l’arbre à cames ne correspond plus à celle du vilebrequin : la distribution est probablement décalée.', 'Camshaft position no longer matches crankshaft position: valve timing is probably shifted.', 'moteur', 'important', 'limited', '["Perte de puissance et à-coups.","Risque de contact soupape/piston sur moteur à distribution critique.","Dégradation rapide si la distribution est détendue."]', '[{"key":"timing_stretched","labelFr":"Chaîne ou courroie de distribution détendue ou sautée d’une dent","labelEn":"Stretched or jumped timing chain or belt","baseRate":0.44,"parts":["kit_distribution"],"confirmedBy":"test_timing_alignment"},{"key":"vvt_solenoid","labelFr":"Électrovanne de calage variable encrassée","labelEn":"Clogged variable valve timing solenoid","baseRate":0.24,"parts":["electrovanne_calage"]},{"key":"cam_sensor_faulty","labelFr":"Capteur d’arbre à cames faussé","labelEn":"Faulty camshaft sensor","baseRate":0.16,"parts":["capteur_arbre_a_cames"]},{"key":"oil_pressure_low","labelFr":"Pression d’huile insuffisante","labelEn":"Insufficient oil pressure","baseRate":0.1,"explainsCodes":["P0016"],"confirmedBy":"test_oil_pressure"},{"key":"phaser_worn","labelFr":"Déphaseur usé","labelEn":"Worn phaser","baseRate":0.06,"parts":["dephaseur"]}]', '["engine_rpm","oil_temp","coolant_temp","timing_advance"]', '["test_timing_alignment","test_oil_pressure","test_cam_sensor_signal"]', '["P0340","P0011"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0351', 'Ignition coil A primary/secondary circuit malfunction', 'Le circuit de la bobine d’allumage A est défaillant : le ou les cylindres concernés ne reçoivent plus d’étincelle fiable.', 'Ignition coil A circuit is faulty: the affected cylinder(s) no longer receive a reliable spark.', 'allumage', 'important', 'limited', '["Ratés d’allumage.","Catalyseur exposé au carburant non brûlé.","Perte de puissance."]', '[{"key":"ignition_coil_1","labelFr":"Bobine d’allumage défaillante","labelEn":"Failed ignition coil","baseRate":0.5,"parts":["bobine_allumage"],"confirmedBy":"test_ignition_spark_check"},{"key":"coil_wiring","labelFr":"Câblage ou connecteur de bobine","labelEn":"Coil wiring or connector","baseRate":0.24,"confirmedBy":"test_wiring_visual"},{"key":"spark_plug_worn","labelFr":"Bougies très usées surchargeant la bobine","labelEn":"Worn spark plugs overloading the coil","baseRate":0.16,"parts":["bougie_allumage"]},{"key":"ecm_driver","labelFr":"Étage de commande du calculateur","labelEn":"ECU driver stage","baseRate":0.1}]', '["engine_rpm","misfire_count","engine_load"]', '["test_ignition_spark_check","test_wiring_visual"]', '["P0300","P0301"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('U0100', 'Lost communication with ECM/PCM "A"', 'Le calculateur moteur a cessé de communiquer sur le réseau du véhicule. Cela peut provoquer un mode dégradé sévère.', 'The engine control module stopped communicating on the vehicle network. This can cause a severe limp mode.', 'reseau', 'important', 'limited', '["Mode dégradé.","Instruments incohérents.","Démarrage impossible selon les cas."]', '[{"key":"can_wiring","labelFr":"Câblage CAN ouvert ou en court-circuit","labelEn":"Open or shorted CAN wiring","baseRate":0.36},{"key":"connector_oxidation","labelFr":"Connecteur oxydé (humidité, poussière)","labelEn":"Corroded connector (moisture, dust)","baseRate":0.3,"confirmedBy":"test_wiring_visual"},{"key":"ground_fault","labelFr":"Masse défectueuse","labelEn":"Faulty ground","baseRate":0.2},{"key":"module_fault","labelFr":"Calculateur défaillant","labelEn":"Failed control module","baseRate":0.14}]', '["battery_voltage"]', '["test_wiring_visual","test_battery_rest_voltage"]', '["U0121","P0562"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('U0121', 'Lost communication with ABS control module', 'XAMOTO ne reçoit plus d’information du calculateur ABS. Les fonctions d’antiblocage et parfois de répartition de freinage sont dégradées.', 'XAMOTO no longer receives information from the ABS control module. Anti-lock and sometimes brake distribution functions are degraded.', 'freinage', 'important', 'with_caution', '["Perte de l’antiblocage : freinage d’urgence dégradé.","Voyants ABS et parfois frein allumés.","Le freinage classique reste généralement disponible, mais l’assistance électronique non."]', '[{"key":"can_wiring","labelFr":"Câblage CAN du calculateur ABS","labelEn":"ABS module CAN wiring","baseRate":0.34},{"key":"abs_module_fault","labelFr":"Calculateur ABS défaillant","labelEn":"Failed ABS module","baseRate":0.28},{"key":"abs_fuse","labelFr":"Fusible d’alimentation ABS","labelEn":"ABS power fuse","baseRate":0.2,"parts":["fusible"]},{"key":"connector_oxidation","labelFr":"Connecteur oxydé","labelEn":"Corroded connector","baseRate":0.18,"confirmedBy":"test_wiring_visual"}]', '["battery_voltage"]', '["test_wiring_visual","test_brake_visual"]', '["U0100","C0035"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('C0035', 'Left front wheel speed sensor circuit', 'Le signal du capteur de vitesse de roue avant gauche est absent ou incohérent. L’ABS et l’antipatinage peuvent être désactivés.', 'Left front wheel speed signal is missing or inconsistent. ABS and traction control may be disabled.', 'freinage', 'important', 'with_caution', '["ABS indisponible.","Voyant ABS allumé.","Compteur ou antipatinage affectés."]', '[{"key":"wheel_sensor_faulty","labelFr":"Capteur de roue défaillant","labelEn":"Faulty wheel speed sensor","baseRate":0.42,"parts":["capteur_abs"],"confirmedBy":"test_wheel_sensor_signal"},{"key":"sensor_ring_dirty","labelFr":"Couronne ou bague magnétique encrassée / abîmée","labelEn":"Dirty or damaged reluctor ring","baseRate":0.26},{"key":"wheel_sensor_wiring","labelFr":"Câblage du capteur (souvent près de la roue)","labelEn":"Sensor wiring (often near the wheel)","baseRate":0.2},{"key":"wheel_bearing_play","labelFr":"Jeu dans le roulement de roue","labelEn":"Wheel bearing play","baseRate":0.12,"parts":["roulement_roue"]}]', '["vehicle_speed","battery_voltage"]', '["test_wheel_sensor_signal","test_brake_visual"]', '["U0121"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0700', 'Transmission control system (MIL request)', 'Le calculateur de boîte de vitesses a détecté un défaut et demande l’allumage du voyant moteur. Le détail se trouve dans le calculateur de boîte.', 'The transmission control module detected a fault and requested the check-engine light. Details are stored in the transmission module.', 'transmission', 'attention', 'with_caution', '["Passages de rapports dégradés ou mode secours.","Usure accélérée si le défaut est ignoré.","XAMOTO a besoin des codes de la boîte (souvent hors OBD standard) pour aller plus loin."]', '[{"key":"transmission_fluid","labelFr":"Huile de boîte dégradée ou niveau incorrect","labelEn":"Degraded transmission fluid or incorrect level","baseRate":0.34,"parts":["huile_boite"]},{"key":"solenoid_faulty","labelFr":"Électrovanne de boîte défaillante","labelEn":"Faulty transmission solenoid","baseRate":0.26},{"key":"sensor_faulty","labelFr":"Capteur de boîte (vitesse, température)","labelEn":"Transmission sensor (speed, temperature)","baseRate":0.2},{"key":"transmission_wiring","labelFr":"Câblage / connecteur de boîte","labelEn":"Transmission wiring / connector","baseRate":0.2,"confirmedBy":"test_wiring_visual"}]', '["vehicle_speed","coolant_temp","battery_voltage"]', '["test_transmission_fluid","test_wiring_visual"]', '["P0715"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0715', 'Input/turbine speed sensor A circuit malfunction', 'Le capteur de vitesse d’entrée de boîte ne renvoie pas un signal correct. La boîte peut passer les rapports de façon erratique.', 'The transmission input speed sensor does not return a correct signal. Gear changes may become erratic.', 'transmission', 'attention', 'with_caution', '["À-coups de transmission.","Mode secours.","Surconsommation."]', '[{"key":"sensor_faulty","labelFr":"Capteur de vitesse d’entrée défaillant","labelEn":"Faulty input speed sensor","baseRate":0.42,"parts":["capteur_boite"]},{"key":"transmission_wiring","labelFr":"Câblage du capteur","labelEn":"Sensor wiring","baseRate":0.26},{"key":"transmission_fluid","labelFr":"Huile de boîte dégradée","labelEn":"Degraded transmission fluid","baseRate":0.2,"parts":["huile_boite"]},{"key":"internal_wear","labelFr":"Usure interne (embrayages, convertisseur)","labelEn":"Internal wear (clutches, converter)","baseRate":0.12}]', '["vehicle_speed","engine_rpm"]', '["test_transmission_fluid","test_wiring_visual"]', '["P0700"]', 'src_xamoto_practice', '1.0.0', '2026-01-01'),
  ('P0606', 'ECM/PCM processor fault', 'Le calculateur signale une anomalie interne. Ce n’est pas une pièce mécanique : l’information doit être vérifiée avant toute intervention.', 'The control module reports an internal fault. This is not a mechanical part: the information must be verified before any intervention.', 'electrique', 'important', 'limited', '["Comportement erratique.","Mode dégradé.","Un défaut de tension ou de masse produit souvent le même code."]', '[{"key":"voltage_instability","labelFr":"Alimentation instable (tension, masse) simulant un défaut calculateur","labelEn":"Unstable supply (voltage, ground) simulating an ECU fault","baseRate":0.42,"confirmedBy":"test_charging_voltage"},{"key":"ecm_software","labelFr":"Version logicielle du calculateur à mettre à jour","labelEn":"ECU software requiring an update","baseRate":0.24},{"key":"ecm_fault","labelFr":"Calculateur réellement défaillant","labelEn":"Genuinely failed control module","baseRate":0.2},{"key":"connector_oxidation","labelFr":"Connecteur calculateur oxydé","labelEn":"Corroded ECU connector","baseRate":0.14,"confirmedBy":"test_wiring_visual"}]', '["battery_voltage","coolant_temp"]', '["test_charging_voltage","test_battery_rest_voltage","test_wiring_visual"]', '["P0562","U0100"]', 'src_xamoto_practice', '1.0.0', '2026-01-01')
